// Сообщение в чате
//
// # Новое созданное сообщение
//
// # Отредактированное сообщение
//
// Отправленное сообщение
type Message struct {
	// Содержимое сообщения. Текст + вложения. Может быть `null`, если сообщение содержит только
	// пересланное сообщение
	Body MessageBody `json:"body"`
	// Пересланное или ответное сообщение
	Link *LinkedMessage `json:"link,omitempty"`
	// Получатель сообщения. Может быть пользователем или чатом
	Recipient Recipient `json:"recipient"`
	// Пользователь, отправивший сообщение
	Sender *User `json:"sender,omitempty"`
	// Статистика сообщения. Возвращается только для постов в каналах
	Stat *MessageStat `json:"stat,omitempty"`
	// Время создания сообщения в формате Unix-time
	Timestamp int64 `json:"timestamp"`
	// Публичная ссылка на пост в канале. Отсутствует для диалогов и групповых чатов. 2048 —
	// официальный лимит URL в оригинальной схеме (LinkButton.url, LinkMarkup.url)
	URL *string `json:"url,omitempty"`
}

// Содержимое сообщения. Текст + вложения. Может быть `null`, если сообщение содержит только
// пересланное сообщение
//
// # Схема, представляющая тело сообщения
//
// Содержимое связанного (пересланного или ответного) сообщения
type MessageBody struct {
	// Вложения сообщения. Могут быть одним из типов `Attachment`. Смотрите описание схемы
	Attachments []Attachment `json:"attachments,omitempty"`
	// Разметка текста сообщения. Для подробной информации загляните в раздел
	// [Форматирование](/docs-api#Форматирование%20текста%20в%20сообщениях)
	Markup []MarkupElement `json:"markup,omitempty"`
	// Уникальный ID сообщения
	Mid string `json:"mid"`
	// ID последовательности сообщения в чате.
	//
	// Единственное int64-поле схемы БЕЗ `@maxValue`: его верхняя граница — предел
	// самого типа (2^63-1), а не «JSON-safe» 2^53-1, как у идентификаторов и
	// времени. `seq` не счётчик, а упакованное значение — старшие биты хранят
	// время создания в миллисекундах, младшие счётчик внутри миллисекунды, — и
	// прод отдаёт величины порядка 1.17e17, на порядок выше 2^53-1 (наблюдение
	// зафиксировано в maxmoc/internal/ids/ids.go: mid
	// `mid.000000001a5b94f2019fdaa593db1d43` разбирается в chat_id 442209522 и
	// seq 117052520019991875). Прежняя граница 2^53-1 отвергала любой честный
	// ответ платформы.
	//
	// Записать 2^63-1 через `@maxValue` нельзя: компилятор TypeSpec держит
	// числовые литералы в JS-числах, и всё выше 2^53-1 теряет точность — эмиттер
	// молча выбрасывает такое ограничение. Явный `maximum` дописывает
	// scripts/apply_int_bounds.py.
	Seq int64 `json:"seq"`
	// Новый текст сообщения. 4000 — официальный лимит текста сообщения (NewMessageBody.text)
	Text *string `json:"text"`
}

// Элемент разметки текста сообщения
//
// Представляет **жирный** текст
//
// Представляет *курсив*
//
// # Представляет `моноширинный` или блок ```код``` в тексте
//
// # Представляет ссылку в тексте
//
// Представляет ~зачёркнутый~ текст
//
// # Представляет подчёркнутый текст
//
// Представляет упоминание пользователя в тексте. Упоминание может быть как по имени
// пользователя, так и по ID, если у пользователя нет имени
//
// # Представляет заголовок
//
// # Представляет выделенный текст
//
// Представляет цитату
type MarkupElement struct {
	// Индекс начала элемента разметки в тексте. Нумерация с нуля
	From int64 `json:"from"`
	// Длина элемента разметки
	Length int64 `json:"length"`
	// Тип элемента разметки: `strong`
	//
	// Тип элемента разметки: `emphasized`
	//
	// Тип элемента разметки: `monospaced`
	//
	// Тип элемента разметки: `link`
	//
	// Тип элемента разметки: `strikethrough`
	//
	// Тип элемента разметки: `underline`
	//
	// Тип элемента разметки: `user_mention`
	//
	// Тип элемента разметки: `heading`
	//
	// Тип элемента разметки: `highlighted`
	//
	// Тип элемента разметки: `quote`
	Type MarkupElementType `json:"type"`
	// URL ссылки. 2048 — значение из официальной схемы MAX
	URL *string `json:"url,omitempty"`
	// ID упомянутого пользователя без имени
	UserID *int64 `json:"user_id,omitempty"`
	// `@username` упомянутого пользователя
	UserLink *string `json:"user_link,omitempty"`
}

