// Объект `Update` описывает возможные события в чате или канале. Может
// возвращаться в следующих случаях:
// - вы подписались на обновления через Webhook — при наступлении события
// МАКС пришлёт POST-запрос `/subscriptions`, который содержит объект `Update`;
// - вы отправили GET-запрос `/updates` для получения обновлений через
// Long Polling — в ответ вернётся объект `Update`.
//
// Явный oneOf всех 16 типов событий — чтобы Swagger UI и генераторы
// показывали полный список вариантов, а не только базовые поля Update
// (allOf-наследование дискриминированного union'а UI не разворачивают).
//
// # Вы получите это событие, как только сообщение будет создано
//
// # Вы получите это событие, как только пользователь нажмёт кнопку
//
// # Вы получите это событие, как только пользователь отредактирует сообщение
//
// # Вы получите это событие, как только сообщение будет удалено
//
// # Вы получите это событие, как только бот будет добавлен в чат или канал
//
// # Вы получите это событие, как только бот будет удалён из чата
//
// Вы получите это событие, как только пользователь начнёт или возобновит
// общение с ботом: нажмёт соответствующую кнопку в настройках бота в МАКС
//
// # Вы получите это событие, как только пользователь остановит бота в его настройках в МАКС
//
// # Вы получите это событие, как только будет изменено название чата
//
// # Вы получите это событие, как только пользователь очистит историю сообщений
//
// Вы получите это событие, как только пользователь отключит уведомления о
// новых сообщениях в диалоге с ботом
//
// Вы получите это событие, как только пользователь включит уведомления о
// новых сообщениях в диалоге с ботом
//
// # Вы получите это событие, как только пользователь удалит чат
//
// Вы получите это событие, как только пользователь будет добавлен в чат,
// где бот является администратором
//
// Вы получите это событие, как только пользователь будет удалён из чата,
// где бот является администратором
//
// Вы получите это событие, как только пользователь нажмёт в сообщении на
// кнопку с типом `chat` и будет создан новый чат с ботом, связанный с этим
// сообщением с кнопкой.
//
// KNOWN: в оригинальной схеме этот дискриминатор отсутствует в
// `Update.discriminator.mapping` (недосмотр оригинала) — см. DEVIATIONS
// `message_chat_created` в scripts/compare.py.
type Update struct {
	// Новое созданное сообщение
	//
	// Изначальное сообщение, содержащее встроенную клавиатуру. Может быть
	// `null`, если оно было удалено к моменту, когда бот получил это событие
	//
	// Отредактированное сообщение
	Message *Message `json:"message,omitempty"`
	// Unix-время, когда произошло событие
	Timestamp int64 `json:"timestamp"`
	// Тип события: `message_created`
	//
	// Тип события: `message_callback`
	//
	// Тип события: `message_edited`
	//
	// Тип события: `message_removed`
	//
	// Тип события: `bot_added`
	//
	// Тип события: `bot_removed`
	//
	// Тип события: `bot_started`
	//
	// Тип события: `bot_stopped`
	//
	// Тип события: `chat_title_changed`
	//
	// Тип события: `dialog_cleared`
	//
	// Тип события: `dialog_muted`
	//
	// Тип события: `dialog_unmuted`
	//
	// Тип события: `dialog_removed`
	//
	// Тип события: `user_added`
	//
	// Тип события: `user_removed`
	//
	// Тип события: `message_chat_created`
	UpdateType UpdateUpdateType `json:"update_type"`
	// Текущий язык пользователя в формате IETF BCP 47. Доступно только в диалогах
	//
	// Текущий язык пользователя в формате IETF BCP 47
	UserLocale *string `json:"user_locale,omitempty"`
	// Нажатая пользователем кнопка
	Callback *Callback `json:"callback,omitempty"`
	// ID чата, где сообщение было удалено. Как получить ID — в разделе «Получение chat_id»
	//
	// ID чата, куда был добавлен бот. Как получить ID — в разделе «Получение chat_id»
	//
	// ID чата, откуда был удалён бот. Как получить ID — в разделе «Получение chat_id»
	//
	// ID диалога, где произошло событие. Как получить ID — в разделе «Получение chat_id»
	//
	// ID чата, где произошло событие. Как получить ID — в разделе «Получение chat_id»
	ChatID *int64 `json:"chat_id,omitempty"`
	// ID удалённого сообщения
	//
	// ID сообщения, где была нажата кнопка
	MessageID *string `json:"message_id,omitempty"`
	// Пользователь, удаливший сообщение
	UserID *int64 `json:"user_id,omitempty"`
	// Указывает, что бот добавлен в канал, а не в чат
	//
	// Указывает, что бот удалён из канала, а не из чата
	//
	// Указывает, что пользователь добавлен в канал, а не в чат
	//
	// Указывает, что пользователь удалён из канала, а не из чата
	IsChannel *bool `json:"is_channel,omitempty"`
	// Пользователь, добавивший бота в чат
	//
	// Пользователь, удаливший бота из чата
	//
	// Пользователь, который нажал кнопку `Start`
	//
	// Пользователь, который остановил бота
	//
	// Пользователь, который изменил название
	//
	// Пользователь, который очистил историю сообщений
	//
	// Пользователь, который отключил уведомления
	//
	// Пользователь, который включил уведомления
	//
	// Пользователь, который удалил чат
	//
	// Пользователь, добавленный в чат
	//
	// Пользователь, удалённый из чата
	User *User `json:"user,omitempty"`
	// Дополнительные данные из диплинков, переданные при запуске бота. 512 — значение из
	// официальной схемы MAX
	Payload *string `json:"payload,omitempty"`
	// Новое название. 200 — официальный лимит названия чата (ChatButton.chat_title,
	// ChatPatch.title)
	Title *string `json:"title,omitempty"`
	// Время в формате Unix, до наступления которого диалог был отключён
	MutedUntil *int64 `json:"muted_until,omitempty"`
	// Пользователь, который добавил нового пользователя в чат. Может быть
	// `null`, если пользователь присоединился к чату по ссылке
	InviterID *int64 `json:"inviter_id,omitempty"`
	// Администратор, который удалил пользователя из чата. Может быть `null`,
	// если пользователь покинул чат сам
	AdminID *int64 `json:"admin_id,omitempty"`
	// Созданный чат
	Chat *Chat `json:"chat,omitempty"`
	// Полезная нагрузка от кнопки чата. 512 — официальный лимит источника значения
	// (ChatButton.start_payload)
	StartPayload *string `json:"start_payload,omitempty"`
}

// Список обновлений о событиях в чатах и каналах, в которые добавлен бот.
// Обратите внимание, чтобы получать события из групповых чатов и каналов,
// бот должен быть администратором
type UpdateList struct {
	// Указатель на следующую страницу данных
	Marker *int64 `json:"marker"`
	// Список обновлений о событиях в чатах и каналах, в которые добавлен бот. 1000 — зеркало
	// максимума параметра limit у GET /updates
	Updates []Update `json:"updates"`
}

// Единая («плоская») схема события: объединение полей всех 16 типов
// `Update` в один объект — в стиле Telegram Bot API. Обязательны только
// `update_type` и `timestamp`; остальные поля приходят в зависимости от
// типа события. Удобна, когда на сервере хочется один класс/структуру
// на все события без union-машинерии.
type UpdateUnified struct {
	// Администратор, удаливший пользователя; отсутствует, если пользователь вышел сам.
	// [user_removed]
	AdminID *int64 `json:"admin_id,omitempty"`
	// Нажатие callback-кнопки. [message_callback]
	Callback *Callback `json:"callback,omitempty"`
	// Созданный чат. [message_chat_created]
	Chat *Chat `json:"chat,omitempty"`
	// ID чата. [bot_added, bot_started, bot_stopped, bot_removed, chat_title_changed,
	// dialog_cleared, dialog_muted, dialog_unmuted, dialog_removed, message_removed,
	// user_added, user_removed]
	ChatID *int64 `json:"chat_id,omitempty"`
	// Кто пригласил пользователя; null, если вошёл по ссылке. [user_added]
	InviterID *int64 `json:"inviter_id,omitempty"`
	// Признак «событие в канале, а не в чате». [bot_added, bot_removed, user_added,
	// user_removed]
	IsChannel *bool `json:"is_channel,omitempty"`
	// Сообщение: новое, отредактированное или с нажатой кнопкой (может быть null).
	// [message_created, message_edited, message_callback]
	Message *Message `json:"message,omitempty"`
	// ID сообщения: удалённого или того, где была нажата кнопка чата. [message_removed,
	// message_chat_created]
	MessageID *string `json:"message_id,omitempty"`
	// До какого времени отключены уведомления (Unix-время). [dialog_muted]
	MutedUntil *int64 `json:"muted_until,omitempty"`
	// Данные из диплинка, переданные при запуске бота. 512 — значение из официальной схемы MAX
	// (BotStartedUpdate.payload). [bot_started]
	Payload *string `json:"payload,omitempty"`
	// Полезная нагрузка кнопки чата. 512 — официальный лимит источника значения
	// (ChatButton.start_payload). [message_chat_created]
	StartPayload *string `json:"start_payload,omitempty"`
	// Unix-время, когда произошло событие
	Timestamp int64 `json:"timestamp"`
	// Новое название чата. 200 — официальный лимит названия чата (ChatButton.chat_title,
	// ChatPatch.title). [chat_title_changed]
	Title *string `json:"title,omitempty"`
	// Тип события: message_created | message_callback | message_edited |
	// message_removed | message_chat_created | bot_added | bot_removed |
	// bot_started | bot_stopped | chat_title_changed | dialog_cleared |
	// dialog_muted | dialog_unmuted | dialog_removed | user_added |
	// user_removed
	UpdateType string `json:"update_type"`
	// Пользователь-инициатор события. [bot_added, bot_started, bot_stopped, bot_removed,
	// chat_title_changed, dialog_cleared, dialog_muted, dialog_unmuted, dialog_removed,
	// user_added, user_removed]
	User *User `json:"user,omitempty"`
	// Автор удалённого сообщения. [message_removed]
	UserID *int64 `json:"user_id,omitempty"`
	// Текущий язык пользователя (IETF BCP 47), доступен только в диалогах. [bot_started,
	// bot_stopped, dialog_cleared, dialog_muted, dialog_unmuted, dialog_removed,
	// message_created, message_callback]
	UserLocale *string `json:"user_locale,omitempty"`
}

// Точка доступа, куда следует загружать ваши бинарные файлы
type UploadEndpoint struct {
	// Токен для отправки медиафайла во вложении к сообщению с помощью POST /messages или PUT
	// /messages. 1024 — в оригинале лимита нет; по аналогии с официальным лимитом кнопочного
	// payload (CallbackButton.payload)
	Token *string `json:"token,omitempty"`
	// URL для загрузки медиафайла. Срок жизни ссылки не ограничен. 2048 — официальный лимит URL
	// в оригинальной схеме (LinkButton.url, LinkMarkup.url)
	URL string `json:"url"`
}

// Вы получите это событие, как только пользователь будет добавлен в чат,
// где бот является администратором
type UserAddedToChatUpdate struct {
	// ID чата, где произошло событие. Как получить ID — в разделе «Получение chat_id»
	ChatID int64 `json:"chat_id"`
	// Пользователь, который добавил нового пользователя в чат. Может быть
	// `null`, если пользователь присоединился к чату по ссылке
	InviterID *int64 `json:"inviter_id,omitempty"`
	// Указывает, что пользователь добавлен в канал, а не в чат
	IsChannel bool `json:"is_channel"`
	// Unix-время, когда произошло событие
	Timestamp int64 `json:"timestamp"`
	// Тип события: `user_added`
	UpdateType UserAddedToChatUpdateUpdateType `json:"update_type"`
	// Пользователь, добавленный в чат
	User User `json:"user"`
}

// Представляет упоминание пользователя в тексте. Упоминание может быть как по имени
// пользователя, так и по ID, если у пользователя нет имени
type UserMentionMarkup struct {
	// Индекс начала элемента разметки в тексте. Нумерация с нуля
	From int64 `json:"from"`
	// Длина элемента разметки
	Length int64 `json:"length"`
	// Тип элемента разметки: `user_mention`
	Type UserMentionMarkupType `json:"type"`
	// ID упомянутого пользователя без имени
	UserID *int64 `json:"user_id,omitempty"`
	// `@username` упомянутого пользователя
	UserLink *string `json:"user_link,omitempty"`
}

// Вы получите это событие, как только пользователь будет удалён из чата,
// где бот является администратором
type UserRemovedFromChatUpdate struct {
	// Администратор, который удалил пользователя из чата. Может быть `null`,
	// если пользователь покинул чат сам
	AdminID *int64 `json:"admin_id,omitempty"`
	// ID чата, где произошло событие. Как получить ID — в разделе «Получение chat_id»
	ChatID int64 `json:"chat_id"`
	// Указывает, что пользователь удалён из канала, а не из чата
	IsChannel bool `json:"is_channel"`
	// Unix-время, когда произошло событие
	Timestamp int64 `json:"timestamp"`
	// Тип события: `user_removed`
	UpdateType UserRemovedFromChatUpdateUpdateType `json:"update_type"`
	// Пользователь, удалённый из чата
	User User `json:"user"`
}

// Вложение видео
type VideoAttachment struct {
	// Длина видео в секундах
	Duration *int64 `json:"duration,omitempty"`
	// Высота видео
	Height *int64 `json:"height,omitempty"`
	// Полезная нагрузка видео-вложения
	Payload MediaAttachmentPayload `json:"payload"`
	// Миниатюра видео
	Thumbnail *VideoThumbnail `json:"thumbnail,omitempty"`
	// Тип вложения: `video`
	Type VideoAttachmentType `json:"type"`
	// Ширина видео
	Width *int64 `json:"width,omitempty"`
}

// Подробная информация о видео-вложении
type VideoAttachmentDetails struct {
	// Длина видео в секундах
	Duration int64 `json:"duration"`
	// Высота видео
	Height int64 `json:"height"`
	// Миниатюра видео
	Thumbnail *PhotoAttachmentPayload `json:"thumbnail,omitempty"`
	// Токен видео-вложения. 1024 — в оригинале лимита нет; по аналогии с официальным лимитом
	// кнопочного payload (CallbackButton.payload)
	Token string `json:"token"`
	// URL-ы для скачивания или воспроизведения видео. Может быть `null`, если видео недоступно
	Urls *VideoUrls `json:"urls,omitempty"`
	// Ширина видео
	Width int64 `json:"width"`
}

// URL-ы видео в разных разрешениях.
//
// Лимит 2048 у всех полей — официальный лимит URL в оригинальной схеме
// (LinkButton.url, LinkMarkup.url).
type VideoUrls struct {
	// URL трансляции, если доступна
	HLS *string `json:"hls,omitempty"`
	// URL видео в разрешении 1080p, если доступно
	Mp41080 *string `json:"mp4_1080,omitempty"`
	// URL видео в разрешении 144p, если доступно
	Mp4144 *string `json:"mp4_144,omitempty"`
	// URL видео в разрешении 240p, если доступно
	Mp4240 *string `json:"mp4_240,omitempty"`
	// URL видео в разрешении 360p, если доступно
	Mp4360 *string `json:"mp4_360,omitempty"`
	// URL видео в разрешении 480p, если доступно
	Mp4480 *string `json:"mp4_480,omitempty"`
	// URL видео в разрешении 720p, если доступно
	Mp4720 *string `json:"mp4_720,omitempty"`
}

// Запрос на прикрепление видео к сообщению
type VideoAttachmentRequest struct {
	// Полезная нагрузка запроса на прикрепление видео
	Payload UploadedInfo `json:"payload"`
	// Тип вложения: `video`
	Type VideoAttachmentType `json:"type"`
}

